 let mapPoint=null;
 $('mapBtn').onclick=()=>{if(!$('satelliteFrame').src)$('satelliteFrame').src='https://maps.google.com/maps?q=-33.5015893,-71.6204554&z=20&t=k&output=embed';$('mapDialog').showModal();};$('closeMap').onclick=()=>$('mapDialog').close();
 $('mapConvert').onclick=()=>{const lat=+$('mapLat').value,lon=+$('mapLon').value;if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){$('mapResult').textContent='Revisa las coordenadas.';return;}mapPoint={x:(lon-geoSettings.longitude)*Math.PI/180*6371000*Math.cos(geoSettings.latitude*d2r),n:(lat-geoSettings.latitude)*Math.PI/180*6371000};$('mapResult').textContent=`Este ${mapPoint.x.toFixed(2)} m · Norte ${mapPoint.n.toFixed(2)} m. Conversión local aproximada.`;};
 $('mapApply').onclick=()=>{if(!mapPoint){toast('Convierte las coordenadas primero.');return;}if(!selected){toast('Selecciona una pieza primero.');return;}const q=placeGroup.worldToLocal(new THREE.Vector3(mapPoint.x,0,-mapPoint.n));Object.assign(selected.spec,{x:q.x,n:-q.z});applySpec(selected);refreshInspector();scheduleAutosave();$('mapDialog').close();toast('Posición geográfica aplicada a la pieza.');};

