 $('insertBtn').onclick=()=>{$('insertError').textContent='';$('insertDialog').showModal();};document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>{$('insertDialog').close();});$('prototypeFile').onchange=e=>{if(e.target.files[0])prepareFile(e.target.files[0]);};
 const zone=$('dropZone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');if(e.dataTransfer.files[0])prepareFile(e.dataTransfer.files[0]);};$('insertForm').onsubmit=submitPrototype;
