 $('includedBtn').onclick=addIncludedPrototype;
 $('focusObject').onclick=()=>focus();$('duplicate').onclick=()=>{if(!selected)return;const p=selected,spec={...p.spec,name:p.spec.name+' · copia',x:p.spec.x+.5};if(p.kind==='image')createImage(sourceLibrary.get(p.sourceId),spec,p.options).then(root=>{addPrototype(root,spec,p.kind,p.sourceId,{...p.options});scheduleAutosave();});else if(p.kind==='demo'){addPrototype(planeAssembly(starPlateGeometry(),spec),spec,'demo',null,{...p.options});scheduleAutosave();}else{const clone=cloneSkeleton(p.root);clone.traverse(o=>{if(o.geometry)o.geometry=o.geometry.clone();if(o.material)o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone();});addPrototype(clone,spec,p.kind,p.sourceId,{...p.options});scheduleAutosave();}};
 $('delete').onclick=()=>{if(selected){disposePrototype(selected);scheduleAutosave();}};
