 $('rotateTool').onclick=()=>{if(!selected){toast('Selecciona una pieza para rotarla.');return;}transform.attach(selected.root);transform.setMode('rotate');transform.showX=!selected.root.userData.assembly;transform.showZ=!selected.root.userData.assembly;transform.showY=true;$('rotateTool').classList.add('active');$('moveTool').classList.remove('active');};
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
