 $('wallSelect').onchange=refreshWallEditor;for(const id of ['wallAE','wallAN','wallBE','wallBN'])$(id).onchange=()=>{const g=wallObjects[+$('wallSelect').value];const v=['wallAE','wallAN','wallBE','wallBN'].map(id=>+$(id).value);if(v.every(Number.isFinite)&&Math.hypot(v[2]-v[0],v[3]-v[1])>.1){g.userData.endpoints=v;rebuildWall(g);refreshWallEditor();renderer.shadowMap.needsUpdate=true;scheduleAutosave();}};refreshWallEditor();bindDimensions();$('walkToggle').onclick=()=>{walk=!walk;cameraTween=null;$('walkToggle').classList.toggle('active',walk);if(walk){photoView?.disable();orbit.minPolarAngle=.04;orbit.maxPolarAngle=Math.PI-.04;toast('Recorrido: W A S D o flechas para moverte. Arrastra para orientar la mirada.');}};$('benchSelect').onchange=refreshBenchEditor;for(const id of ['benchEast','benchNorth','benchHeading'])$(id).onchange=()=>{const g=benchObjects[+$('benchSelect').value];g.position.set(+$('benchEast').value,0,-+$('benchNorth').value);g.rotation.y=(90-Number($('benchHeading').value))*d2r;renderer.shadowMap.needsUpdate=true;scheduleAutosave();};refreshBenchEditor();
 for(const key of Object.keys(geoSettings))$(key).onchange=()=>{const value=+$(key).value;if(!Number.isFinite(value))return;if(key==='latitude'&&Math.abs(value)>89){toast('La latitud debe estar entre −89 y 89°.');return;}if(key==='longitude'&&Math.abs(value)>180){toast('La longitud debe estar entre −180 y 180°.');return;}geoSettings[key]=value;if(key.startsWith('ground')){updateGround();prototypes.forEach(applySpec);}placeGroup.rotation.y=-geoSettings.siteRotation*d2r;if(key==='siteRotation'){northVerified=false;$('northVerified').checked=false;}updateNorthStatus();updateSun();scheduleAutosave();};
 $('showPlanAngles').onchange=scheduleAutosave;$('showSun').onchange=()=>sunGuide.visible=$('showSun').checked;$('showGrid').onchange=()=>grid.visible=$('showGrid').checked||mode==='analysis';$('contextToggle').onclick=()=>{photoView?.disable();$('showSite').checked=!$('showSite').checked;setSiteVisibility();scheduleAutosave();};$('showSite').onchange=()=>{setSiteVisibility();};$('shadowQuality').onchange=()=>setMode(mode);
 $('saveProject').onclick=saveProject;$('openProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>90*1024*1024)throw new Error('El proyecto supera 90 MB.');toast('Abriendo proyecto…');await restoreProject(JSON.parse(await file.text()));saveSnapshot(projectData());}catch(err){toast(err.message);}e.target.value='';};
 $('importSite').onclick=()=>$('siteFile').click();$('siteFile').onchange=e=>{if(e.target.files[0])importEnvironment(e.target.files[0]);e.target.value='';};$('clearSite').onclick=()=>{if(importedSite){importedSite.parent?.remove(importedSite);importedSite=null;$('clearSite').hidden=true;setSiteVisibility();scheduleAutosave();}};
