 $('referenceBtn').onclick=()=>$('referenceDialog').showModal();document.querySelectorAll('.close-reference').forEach(b=>b.onclick=()=>$('referenceDialog').close());$('photoTab').onclick=()=>{$('sitePhoto').src='assets/referencia-lugar.png';$('sitePhoto').hidden=false;$('tourFrame').hidden=true;$('aerialTab').classList.remove('active');$('photoTab').classList.add('active');$('tourTab').classList.remove('active');};$('aerialTab').onclick=()=>{$('sitePhoto').src='assets/referencia-aerea.png';$('sitePhoto').hidden=false;$('tourFrame').hidden=true;$('aerialTab').classList.add('active');$('photoTab').classList.remove('active');$('tourTab').classList.remove('active');};$('tourTab').onclick=()=>{$('aerialTab').classList.remove('active');if(!$('tourFrame').src)$('tourFrame').src='https://patrimoniovirtual.cl/tvp/vt21/index.htm';$('sitePhoto').hidden=true;$('tourFrame').hidden=false;$('tourTab').classList.add('active');$('photoTab').classList.remove('active');};
 document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('insertDialog').open||$('referenceDialog').open)return;if(e.key==='Escape'){pickPoint=false;renderer.domElement.style.cursor='';transform.detach();select(null);}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();if(selected){disposePrototype(selected);scheduleAutosave();}}if(e.key.toLowerCase()==='f')focus();});
