window.StellaSolar={photo:()=>photoView,solarPosition,zonedInstant,SITE,getState:()=>({clock:{...clock},solar:sunState,cameraRelation:cameraSunRelation(),benches:benchObjects.map(g=>({position:g.position.toArray(),heading:90-g.rotation.y/d2r})),walls:wallObjects.map(g=>({endpoints:[...g.userData.endpoints]})),dimensions:{...dimensions},planReference,annotationCount:planAnnotations?.children.length||0,coastalBarrier:{segments:2,height:dimensions.wallHeight,pillarHeight:dimensions.pillarHeight,bounds:coastalBarrier?new THREE.Box3().setFromObject(coastalBarrier).getSize(new THREE.Vector3()).toArray():null},northVerified,contextVisible:$('showSite').checked,worldPositions:prototypes.map(p=>p.root.getWorldPosition(new THREE.Vector3()).toArray()),skyGuidePosition:sunGuide.position.toArray(),cameraPosition:camera.position.toArray(),walking:walk,walkKeys:[...walkKeys],photographic:photoView?.getData(),objects:prototypes.map(p=>({kind:p.kind,spec:{...p.spec},size:new THREE.Box3().setFromObject(p.root).getSize(new THREE.Vector3()).toArray()})),renderer:renderer?.info.render}),addDemo,projectData,setView,auditGroundPoint:(east,north)=>{if(!sunState||sunState.elevation<=0)return null;scene.updateMatrixWorld(true);const origin=new THREE.Vector3(east,groundHeight(east,north)+.0005,-north);const dir=sun.position.clone().normalize();const r=new THREE.Raycaster(origin,dir,.0001,120);const meshes=[];objectsGroup.traverse(o=>{if(o.isMesh&&o.visible)meshes.push(o);});return r.intersectObjects(meshes,false).map(h=>({distance:h.distance,name:h.object.name}));}};
